/*!40101 SET @OLD_CHARACTER_SET_CLIENT=@@CHARACTER_SET_CLIENT */;
/*!40101 SET NAMES utf8 */;
/*!50503 SET NAMES utf8mb4 */;
/*!40103 SET @OLD_TIME_ZONE=@@TIME_ZONE */;
/*!40103 SET TIME_ZONE='+00:00' */;
/*!40014 SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0 */;
/*!40101 SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO' */;
/*!40111 SET @OLD_SQL_NOTES=@@SQL_NOTES, SQL_NOTES=0 */;

CREATE TABLE IF NOT EXISTS `acl_menu_groups` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `sort` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4149 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `acl_permissions` (
  `role_id` int(10) unsigned NOT NULL,
  `resource_id` int(10) unsigned NOT NULL,
  `can_view` tinyint(1) NOT NULL DEFAULT 0,
  `can_add` tinyint(1) NOT NULL DEFAULT 0,
  `can_edit` tinyint(1) NOT NULL DEFAULT 0,
  `can_del` tinyint(1) NOT NULL DEFAULT 0,
  `can_exec` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`role_id`,`resource_id`),
  KEY `fk_perm_resource` (`resource_id`),
  CONSTRAINT `fk_perm_resource` FOREIGN KEY (`resource_id`) REFERENCES `acl_resources` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_perm_role` FOREIGN KEY (`role_id`) REFERENCES `acl_roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `acl_resources` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(64) NOT NULL,
  `name` varchar(200) NOT NULL,
  `group_id` int(10) unsigned NOT NULL,
  `sort` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `fk_res_group` (`group_id`),
  CONSTRAINT `fk_res_group` FOREIGN KEY (`group_id`) REFERENCES `acl_menu_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4167 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `acl_roles` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(64) NOT NULL,
  `name` varchar(200) NOT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=3041 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `acl_staff` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `login` varchar(50) DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `auth_type` enum('local','ldap') NOT NULL DEFAULT 'local',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_protected` tinyint(1) NOT NULL DEFAULT 0,
  `fio` varchar(100) DEFAULT NULL,
  `role_id` int(10) unsigned DEFAULT NULL,
  `login_date` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_new` (`id`),
  KEY `fk_staff_role` (`role_id`),
  CONSTRAINT `fk_staff_role` FOREIGN KEY (`role_id`) REFERENCES `acl_roles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `app_settings` (
  `name` varchar(64) NOT NULL,
  `value` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `auth_login_attempts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ip` varchar(45) NOT NULL DEFAULT '',
  `login` varchar(100) NOT NULL DEFAULT '',
  `attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  `last_attempt_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_auth_attempt_ip_login` (`ip`,`login`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `backup_device_status` (
  `device` varchar(150) NOT NULL COMMENT 'имя устройства (как в бэкапах)',
  `kind` enum('hw','site') NOT NULL DEFAULT 'hw',
  `last_attempt_at` datetime NOT NULL,
  `last_ok` tinyint(1) NOT NULL DEFAULT 0,
  `error` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`device`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `brand` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `brand_name` varchar(128) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `Индекс 2` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `collector_jobs` (
  `job_key` varchar(50) NOT NULL,
  `name` varchar(100) NOT NULL,
  `command` varchar(500) NOT NULL,
  `schedule` varchar(50) NOT NULL DEFAULT '',
  `cron` varchar(50) NOT NULL DEFAULT '',
  `description` varchar(255) NOT NULL DEFAULT '',
  `flag_key` varchar(80) NOT NULL DEFAULT '',
  PRIMARY KEY (`job_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `credentials` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) DEFAULT NULL,
  `login` varchar(100) NOT NULL,
  `pas` text NOT NULL,
  `enable_pas` text DEFAULT NULL,
  `port_api` int(11) DEFAULT NULL COMMENT 'MikroTik API (8728)',
  `port_api_ssl` int(11) DEFAULT NULL COMMENT 'MikroTik API-SSL (8729)',
  `port_ssh` int(11) DEFAULT NULL COMMENT 'SSH (22)',
  PRIMARY KEY (`id`),
  KEY `idx_credentials_login` (`login`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `device_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `description` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `hardware` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_model` int(11) NOT NULL,
  `switch_name` varchar(50) DEFAULT NULL,
  `hardware_ip` varchar(64) NOT NULL,
  `poe` tinyint(1) DEFAULT 0,
  `active` tinyint(4) DEFAULT 0,
  `locations_id` int(11) DEFAULT NULL,
  `rooms_id` int(11) DEFAULT NULL,
  `cred_id` int(11) DEFAULT NULL,
  `firmware_version` varchar(100) DEFAULT NULL COMMENT 'Прошивка / OS version',
  `bootloader_version` varchar(100) DEFAULT NULL COMMENT 'Bootloader / RouterBOOT',
  `serial_number` varchar(100) DEFAULT NULL COMMENT 'Серийный номер',
  `model_name` varchar(100) DEFAULT NULL COMMENT 'Модель с устройства',
  `uptime` varchar(100) DEFAULT NULL COMMENT 'Uptime',
  `temperature` decimal(5,1) DEFAULT NULL COMMENT 'Температура °C',
  `poe_budget` decimal(8,1) DEFAULT NULL COMMENT 'PoE бюджет, W',
  `poe_consumption` decimal(8,1) DEFAULT NULL COMMENT 'PoE потребление, W',
  `ssh_legacy` tinyint(1) DEFAULT NULL COMMENT 'SSH-режим: NULL=авто (modern→legacy), 1=legacy-first, 0=modern. Ставит harvest; сброс при смене прошивки',
  PRIMARY KEY (`id`),
  KEY `id_model` (`id_model`),
  CONSTRAINT `hardware_ibfk_1` FOREIGN KEY (`id_model`) REFERENCES `model` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `hw_ping_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `hardware_id` int(11) NOT NULL,
  `checked_at` datetime NOT NULL,
  `is_up` tinyint(1) NOT NULL,
  `rtt_ms` decimal(8,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_hw_time` (`hardware_id`,`checked_at`),
  KEY `idx_time` (`checked_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `hw_ping_state` (
  `hardware_id` int(11) NOT NULL,
  `is_up` tinyint(1) NOT NULL DEFAULT 0,
  `rtt_ms` decimal(8,2) DEFAULT NULL COMMENT 'Время отклика, мс',
  `last_change` datetime DEFAULT NULL COMMENT 'Когда состояние изменилось последний раз',
  `checked_at` datetime DEFAULT NULL COMMENT 'Когда устройство последний раз опрашивалось',
  `method` varchar(20) NOT NULL DEFAULT 'ping' COMMENT 'Чем проверяли',
  `down_streak` int(11) NOT NULL DEFAULT 0 COMMENT 'Подряд неудачных проверок',
  PRIMARY KEY (`hardware_id`),
  CONSTRAINT `fk_ping_hw` FOREIGN KEY (`hardware_id`) REFERENCES `hardware` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `hw_state_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `hardware_id` int(11) NOT NULL,
  `changed_at` datetime NOT NULL COMMENT 'Когда состояние сменилось',
  `is_up` tinyint(1) NOT NULL COMMENT 'Новое состояние',
  PRIMARY KEY (`id`),
  KEY `idx_hw_time` (`hardware_id`,`changed_at`),
  KEY `idx_time` (`changed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='События смены доступности (долгая история аптайма)';


CREATE TABLE IF NOT EXISTS `incidents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `hardware_id` int(11) NOT NULL,
  `started_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL COMMENT 'NULL = инцидент открыт (устройство down)',
  `cause` varchar(32) NOT NULL DEFAULT '' COMMENT 'power|access|provider|hardware|config|other|""=не указана',
  `comment` varchar(500) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_hw` (`hardware_id`),
  KEY `idx_started` (`started_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `ipam_addresses` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `subnet_id` int(10) unsigned NOT NULL,
  `ip` int(10) unsigned NOT NULL,
  `hw_id` int(11) DEFAULT NULL,
  `status` enum('assigned','reserved','conflict','offline') NOT NULL DEFAULT 'assigned',
  `source` enum('manual','dhcp','scan') NOT NULL DEFAULT 'manual',
  `ip_source` enum('dhcp_dynamic','dhcp_static','arp_only') DEFAULT NULL,
  `hostname` varchar(255) DEFAULT NULL,
  `mac` char(17) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `assigned_at` datetime DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ipam_subnet_ip` (`subnet_id`,`ip`),
  KEY `idx_ipam_ip` (`ip`),
  KEY `idx_ipam_addr_hw` (`hw_id`),
  KEY `idx_ipam_addr_status` (`status`),
  KEY `idx_ipam_addr_mac` (`mac`),
  CONSTRAINT `fk_ipam_addr_hw` FOREIGN KEY (`hw_id`) REFERENCES `hardware` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ipam_addr_subnet` FOREIGN KEY (`subnet_id`) REFERENCES `ipam_subnets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `ipam_history` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `address_id` int(10) unsigned NOT NULL,
  `action` enum('assign','release','reserve','change','conflict') NOT NULL,
  `old_status` varchar(16) DEFAULT NULL,
  `new_status` varchar(16) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `comment` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ipam_hist_addr` (`address_id`),
  KEY `idx_ipam_hist_created` (`created_at`),
  CONSTRAINT `fk_ipam_hist_addr` FOREIGN KEY (`address_id`) REFERENCES `ipam_addresses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `ipam_matrix` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `src_vlan_id` smallint(5) unsigned NOT NULL COMMENT 'VLAN-источник (ipam_vlans.id)',
  `dst_type` enum('vlan','internet') NOT NULL DEFAULT 'vlan' COMMENT 'Тип назначения',
  `dst_vlan_id` smallint(5) unsigned DEFAULT NULL COMMENT 'VLAN-назначение; NULL = Internet',
  `dst_key` smallint(5) unsigned GENERATED ALWAYS AS (ifnull(`dst_vlan_id`,0)) STORED,
  `action` enum('accept','drop') NOT NULL,
  `comment` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_matrix_pair` (`src_vlan_id`,`dst_type`,`dst_key`),
  KEY `idx_matrix_dst` (`dst_vlan_id`),
  CONSTRAINT `fk_matrix_dst` FOREIGN KEY (`dst_vlan_id`) REFERENCES `ipam_vlans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_matrix_src` FOREIGN KEY (`src_vlan_id`) REFERENCES `ipam_vlans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Матрица межсетевого доступа VLAN';


CREATE TABLE IF NOT EXISTS `ipam_subnets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `vlan_ref_id` smallint(5) unsigned NOT NULL,
  `network` int(10) unsigned NOT NULL,
  `prefix_len` tinyint(3) unsigned NOT NULL,
  `gateway` int(10) unsigned DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ipam_net_prefix` (`network`,`prefix_len`),
  KEY `idx_ipam_subnet_vlan` (`vlan_ref_id`),
  CONSTRAINT `fk_ipam_subnet_vlan` FOREIGN KEY (`vlan_ref_id`) REFERENCES `ipam_vlans` (`id`),
  CONSTRAINT `chk_ipam_prefix_len` CHECK (`prefix_len` between 0 and 32)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `ipam_vlans` (
  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
  `hw_id` int(11) NOT NULL,
  `vlan_id` smallint(5) unsigned NOT NULL,
  `name` varchar(64) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ipam_vlan_hw_num` (`hw_id`,`vlan_id`),
  KEY `idx_ipam_vlan_name` (`name`),
  CONSTRAINT `fk_ipam_vlan_hw` FOREIGN KEY (`hw_id`) REFERENCES `hardware` (`id`),
  CONSTRAINT `chk_ipam_vlan_range` CHECK (`vlan_id` between 1 and 4094)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `job_run_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `job_key` varchar(50) NOT NULL,
  `params` varchar(255) DEFAULT NULL,
  `requested_by` varchar(64) NOT NULL DEFAULT '',
  `requested_at` datetime NOT NULL DEFAULT current_timestamp(),
  `status` enum('pending','running','done','failed') NOT NULL DEFAULT 'pending',
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `exit_code` int(11) DEFAULT NULL,
  `output` mediumtext DEFAULT NULL,
  `progress_total` int(11) DEFAULT NULL COMMENT 'всего единиц работы',
  `progress_done` int(11) DEFAULT NULL COMMENT 'выполнено',
  `progress_current` varchar(255) DEFAULT NULL COMMENT 'что обрабатывается сейчас',
  `progress_at` datetime DEFAULT NULL COMMENT 'последнее обновление прогресса (heartbeat)',
  PRIMARY KEY (`id`),
  KEY `status` (`status`),
  KEY `job_key` (`job_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `locations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) DEFAULT NULL,
  `code` varchar(50) DEFAULT NULL,
  `new_name` varchar(255) DEFAULT NULL,
  `tz_offset_msk` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Сдвиг времени от Москвы, часы',
  `work_schedule` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Расписание: {"mon":[["09:00","18:00"]],...}',
  `address` mediumtext DEFAULT NULL,
  `gps` varchar(100) DEFAULT NULL,
  `status` tinyint(1) DEFAULT 1,
  `type_id` int(11) DEFAULT NULL,
  `comment` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `type_id` (`type_id`),
  KEY `status` (`status`),
  KEY `idx_tz_offset` (`tz_offset_msk`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `locations_rooms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `locations_id` int(11) NOT NULL,
  `name` varchar(150) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `locations_type` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT 'Порядок сортировки (важность)',
  `description` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `maps` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `comment` varchar(500) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `map_groups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `map_id` int(11) NOT NULL DEFAULT 1,
  `label` varchar(200) NOT NULL DEFAULT '',
  `x` double NOT NULL DEFAULT 0,
  `y` double NOT NULL DEFAULT 0,
  `w` double NOT NULL DEFAULT 300,
  `h` double NOT NULL DEFAULT 200,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `map_links` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `map_id` int(11) NOT NULL DEFAULT 1,
  `src_node` int(11) NOT NULL,
  `dst_node` int(11) NOT NULL,
  `src_port` varchar(50) DEFAULT NULL COMMENT 'Порт на стороне источника (P48, sfp28-1)',
  `dst_port` varchar(50) DEFAULT NULL COMMENT 'Порт на стороне приёмника',
  `speed` varchar(20) DEFAULT NULL COMMENT '1G|10G|25G|40G|100G',
  `label` varchar(200) DEFAULT NULL COMMENT 'Свободная подпись (договор, VLAN и т.п.)',
  `color` varchar(20) DEFAULT NULL COMMENT 'Цвет линии: gray|red|blue|green|orange|purple',
  `line` varchar(10) NOT NULL DEFAULT 'smooth' COMMENT 'smooth|straight',
  PRIMARY KEY (`id`),
  KEY `map_id` (`map_id`),
  KEY `src_node` (`src_node`),
  KEY `dst_node` (`dst_node`),
  CONSTRAINT `fk_map_links_dst` FOREIGN KEY (`dst_node`) REFERENCES `map_nodes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_map_links_src` FOREIGN KEY (`src_node`) REFERENCES `map_nodes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `map_link_points` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `link_id` int(11) NOT NULL,
  `seq` int(11) NOT NULL DEFAULT 0 COMMENT 'Порядок точки в цепочке',
  `x` float DEFAULT NULL,
  `y` float DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `link_id` (`link_id`),
  CONSTRAINT `fk_mlp_link` FOREIGN KEY (`link_id`) REFERENCES `map_links` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `map_nodes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `map_id` int(11) NOT NULL DEFAULT 1,
  `hardware_id` int(11) DEFAULT NULL COMMENT 'Привязка к hardware; NULL — свободный узел (Интернет и т.п.)',
  `label` varchar(200) NOT NULL,
  `comment` varchar(255) DEFAULT NULL,
  `role` varchar(20) NOT NULL DEFAULT 'other' COMMENT 'router|core|access|server|provider|reserved|other',
  `x` float DEFAULT NULL,
  `y` float DEFAULT NULL,
  `icon` varchar(100) DEFAULT NULL COMMENT 'Файл иконки из custom/; NULL — иконка по типу узла',
  `check_type` varchar(20) NOT NULL DEFAULT 'ping' COMMENT 'Как мониторить: ping|http|https|tcp|dns|ssh|snmp',
  `check_port` int(11) DEFAULT NULL COMMENT 'Порт для tcp-проверки',
  PRIMARY KEY (`id`),
  KEY `map_id` (`map_id`),
  KEY `hardware_id` (`hardware_id`),
  CONSTRAINT `fk_map_nodes_hw` FOREIGN KEY (`hardware_id`) REFERENCES `hardware` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `map_settings` (
  `map_id` int(11) NOT NULL,
  `font_size` tinyint(4) NOT NULL DEFAULT 13 COMMENT 'Размер шрифта имени, px',
  `icon_size` tinyint(4) NOT NULL DEFAULT 24 COMMENT 'Размер пиктограммы, px',
  `show_model` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Показывать строку модели',
  `show_ip` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Показывать строку IP-адреса',
  `show_firmware` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Строка прошивки',
  `show_uptime` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Строка uptime',
  `show_temp` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Строка температуры',
  `show_comment` tinyint(1) NOT NULL DEFAULT 0,
  `style` text DEFAULT NULL COMMENT 'JSON: block/selection/links/icons/background',
  `icon_img_max` smallint(6) NOT NULL DEFAULT 96 COMMENT 'Максимальный размер иконки после сжатия, px',
  PRIMARY KEY (`map_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `model` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_brand` int(11) NOT NULL,
  `model_name` varchar(128) DEFAULT NULL,
  `poe_ports` int(11) DEFAULT NULL,
  `ports` int(11) DEFAULT NULL,
  `port` int(11) DEFAULT NULL,
  `model_type_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_brand` (`id_brand`),
  CONSTRAINT `model_ibfk_1` FOREIGN KEY (`id_brand`) REFERENCES `brand` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `model_type` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'Свич, Роутер, ...',
  `description` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_backups` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `locations_id` bigint(20) unsigned NOT NULL,
  `file_type` enum('rsc','backup','cfg') NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `file_path` varchar(512) NOT NULL,
  `file_size` bigint(20) unsigned NOT NULL,
  `file_mtime` datetime NOT NULL,
  `sha256` char(64) DEFAULT NULL,
  `prev_id` bigint(20) unsigned DEFAULT NULL,
  `changed_vs_prev` tinyint(1) DEFAULT NULL,
  `indexed_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_path` (`file_path`(255)),
  KEY `idx_loc_type_mtime` (`locations_id`,`file_type`,`file_mtime`),
  KEY `idx_prev` (`prev_id`),
  CONSTRAINT `fk_mt_backups_loc` FOREIGN KEY (`locations_id`) REFERENCES `locations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_backup_diffs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `from_id` bigint(20) unsigned NOT NULL,
  `to_id` bigint(20) unsigned NOT NULL,
  `added` int(10) unsigned NOT NULL DEFAULT 0,
  `removed` int(10) unsigned NOT NULL DEFAULT 0,
  `diff_json` longtext DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_pair` (`from_id`,`to_id`),
  KEY `idx_to` (`to_id`),
  KEY `idx_created` (`created_at`),
  CONSTRAINT `fk_bkp_diff_from` FOREIGN KEY (`from_id`) REFERENCES `mt_backups` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_bkp_diff_to` FOREIGN KEY (`to_id`) REFERENCES `mt_backups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_devices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `current_firmware` varchar(50) DEFAULT NULL,
  `upgrade_firmware` varchar(50) DEFAULT NULL,
  `locations_id` int(11) DEFAULT NULL,
  `hostname` varchar(100) NOT NULL,
  `radius` int(2) DEFAULT NULL,
  `ip` varchar(45) NOT NULL,
  `mac` varchar(50) DEFAULT NULL,
  `board_name` varchar(100) DEFAULT NULL,
  `version` varchar(50) DEFAULT NULL,
  `cpu_count` int(11) DEFAULT NULL,
  `cpu_frequency` varchar(50) DEFAULT NULL,
  `total_memory` bigint(20) DEFAULT NULL,
  `free_memory` bigint(20) DEFAULT NULL,
  `uptime` int(11) DEFAULT NULL,
  `model` varchar(100) DEFAULT NULL,
  `serial_number` varchar(50) DEFAULT NULL,
  `last_check` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `status` enum('ok','error') DEFAULT 'ok',
  `error_message` text DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `hostname` (`hostname`) USING BTREE,
  KEY `idx_hostname` (`hostname`) USING BTREE,
  KEY `idx_ip` (`ip`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE IF NOT EXISTS `mt_history_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `run_id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL,
  `hostname` varchar(128) NOT NULL,
  `ip` varchar(64) NOT NULL,
  `success` tinyint(1) NOT NULL DEFAULT 0,
  `error_text` text DEFAULT NULL,
  `output` mediumtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `run_id` (`run_id`),
  KEY `site_id` (`site_id`),
  CONSTRAINT `mt_history_items_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `mt_history_runs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_history_runs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `user_fio` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `mode` enum('run','dry','debug') NOT NULL DEFAULT 'run',
  `commands_text` mediumtext NOT NULL,
  `total` int(11) NOT NULL DEFAULT 0,
  `ok_count` int(11) NOT NULL DEFAULT 0,
  `fail_count` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `created_at` (`created_at`),
  KEY `user_id` (`user_id`),
  KEY `mode` (`mode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_pool_allocations` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pool_id` int(11) NOT NULL,
  `network_ip` varchar(45) NOT NULL COMMENT 'Сетевой адрес блока (10.77.42.0)',
  `block_bits` tinyint(3) unsigned NOT NULL,
  `site_id` int(11) NOT NULL,
  `allocated_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pool_block` (`pool_id`,`network_ip`,`block_bits`),
  KEY `idx_site` (`site_id`),
  CONSTRAINT `mt_pool_allocations_ibfk_1` FOREIGN KEY (`pool_id`) REFERENCES `mt_pool_ranges` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_pool_groups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(32) NOT NULL,
  `name` varchar(64) NOT NULL,
  `sort` int(11) NOT NULL DEFAULT 100,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_pool_purposes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(32) NOT NULL,
  `name` varchar(64) NOT NULL,
  `kind` enum('subnet','host') NOT NULL DEFAULT 'subnet',
  `default_bits` tinyint(3) unsigned NOT NULL,
  `icon` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_pool_ranges` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) DEFAULT NULL,
  `purpose` varchar(32) NOT NULL,
  `name` varchar(64) NOT NULL,
  `cidr` varchar(64) NOT NULL,
  `kind` enum('subnet','host') NOT NULL DEFAULT 'subnet',
  `step_bits` tinyint(3) unsigned NOT NULL,
  `priority` int(11) NOT NULL DEFAULT 100,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `comment` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_name` (`name`),
  KEY `idx_group_purpose` (`group_id`,`purpose`),
  KEY `purpose` (`purpose`),
  CONSTRAINT `mt_pool_ranges_ibfk_1` FOREIGN KEY (`group_id`) REFERENCES `mt_pool_groups` (`id`),
  CONSTRAINT `mt_pool_ranges_ibfk_2` FOREIGN KEY (`purpose`) REFERENCES `mt_pool_purposes` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_run_slots` (
  `slot` tinyint(4) NOT NULL,
  `title` varchar(255) NOT NULL DEFAULT '',
  `commands` mediumtext DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`slot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_run_slot_items` (
  `slot` tinyint(4) NOT NULL,
  `site_id` int(11) NOT NULL,
  `status` enum('ok','fail') NOT NULL,
  `error_text` text DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`slot`,`site_id`),
  KEY `idx_slot` (`slot`),
  CONSTRAINT `fk_slot_items_slot` FOREIGN KEY (`slot`) REFERENCES `mt_run_slots` (`slot`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_sites` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `locations_id` int(11) DEFAULT NULL,
  `group_id` int(11) DEFAULT NULL,
  `cred_id` int(11) DEFAULT NULL,
  `lte_router` tinyint(4) DEFAULT 0,
  `usb_modem` tinyint(4) DEFAULT 0,
  `ip1` varchar(45) DEFAULT NULL,
  `gw1` varchar(45) DEFAULT NULL,
  `dns1` varchar(45) DEFAULT NULL,
  `dhcpclient1` tinyint(4) DEFAULT 0,
  `ip2` varchar(45) DEFAULT NULL,
  `gw2` varchar(45) DEFAULT NULL,
  `dns2` varchar(45) DEFAULT NULL,
  `dhcpclient2` tinyint(4) DEFAULT 0,
  `lan` varchar(45) DEFAULT NULL,
  `lan_old` varchar(45) DEFAULT NULL,
  `ip_video` varchar(45) DEFAULT NULL,
  `ip_ipip_salons` varchar(45) DEFAULT NULL,
  `ip_ipip_router1` varchar(45) DEFAULT NULL,
  `routerid_vpn1` varchar(45) DEFAULT NULL,
  `routerid_vpn2` varchar(45) DEFAULT NULL,
  `lo` varchar(45) DEFAULT NULL,
  `ip_wg` varchar(45) DEFAULT NULL,
  `wg_private` text DEFAULT NULL,
  `wg_public` text DEFAULT NULL,
  `guest_vlan_ip` varchar(45) DEFAULT NULL,
  `sstp_password` varchar(25) DEFAULT NULL,
  `sstp` tinyint(4) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_location` (`locations_id`),
  KEY `idx_group` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE IF NOT EXISTS `mt_tasks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL DEFAULT '',
  `comment` text DEFAULT NULL,
  `status` enum('active','archived') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) NOT NULL DEFAULT 0,
  `created_fio` varchar(255) NOT NULL DEFAULT '',
  `closed_at` datetime DEFAULT NULL,
  `closed_by` int(11) NOT NULL DEFAULT 0,
  `closed_fio` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `mt_task_marks` (
  `task_id` int(11) NOT NULL,
  `site_id` int(11) NOT NULL,
  `marked_at` datetime NOT NULL DEFAULT current_timestamp(),
  `marked_by` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`task_id`,`site_id`),
  KEY `idx_site` (`site_id`),
  CONSTRAINT `fk_task_marks_task` FOREIGN KEY (`task_id`) REFERENCES `mt_tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `oui_vendors` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `prefix_plain` char(6) NOT NULL,
  `vendor_name` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Индекс 2` (`prefix_plain`)
) ENGINE=InnoDB AUTO_INCREMENT=38508 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `phone` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `phone_number` varchar(20) NOT NULL,
  `phone_ip` varchar(45) NOT NULL,
  `datetime` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `phone_number` (`phone_number`),
  KEY `Индекс 3` (`phone_ip`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `settings` (
  `key` varchar(50) NOT NULL,
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Описание настройки',
  `value` varchar(255) NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `sw_cfg_port` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `hardware_id` int(11) NOT NULL,
  `port` varchar(64) NOT NULL COMMENT 'Имя порта в конфиге (0/45, 1/0/24, sfp28-1)',
  `port_num` int(11) DEFAULT NULL COMMENT 'Числовой номер (для связи со sw_port_info и портами карты)',
  `mode` enum('access','trunk','routed','unknown') NOT NULL DEFAULT 'unknown',
  `pvid` int(11) DEFAULT NULL COMMENT 'Native/untagged VLAN',
  `tagged` text DEFAULT NULL COMMENT 'Tagged VLAN через запятую; ALL — разрешены все',
  `untagged` text DEFAULT NULL COMMENT 'Доп. untagged VLAN через запятую (MikroTik bridge vlan)',
  `descr` varchar(255) DEFAULT NULL COMMENT 'description/comment порта из конфига',
  `src_file` varchar(255) DEFAULT NULL COMMENT 'Файл бэкапа, из которого спарсено',
  `parsed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_hw_port` (`hardware_id`,`port`),
  KEY `idx_hw_num` (`hardware_id`,`port_num`),
  CONSTRAINT `fk_sw_cfg_port_hw` FOREIGN KEY (`hardware_id`) REFERENCES `hardware` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `sw_port_fdb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_switch` int(11) NOT NULL,
  `port` int(11) NOT NULL,
  `port_mac` char(17) NOT NULL,
  `vendor_id` int(11) DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `potr` (`port`) USING BTREE,
  KEY `mac` (`port_mac`) USING BTREE,
  KEY `idx_switch_port` (`id_switch`,`port`),
  CONSTRAINT `sw_port_fdb_ibfk_1` FOREIGN KEY (`id_switch`) REFERENCES `hardware` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `sw_port_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_switch` int(11) NOT NULL,
  `port` int(11) NOT NULL,
  `port_name` varchar(64) DEFAULT NULL,
  `mac_count` int(11) DEFAULT 0,
  `poe` varchar(16) DEFAULT 'unknown',
  `speed` int(11) DEFAULT NULL,
  `port_status` enum('up','down') DEFAULT 'down',
  `last_active` datetime DEFAULT NULL,
  `last_down` datetime DEFAULT NULL,
  `scanned_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `port` (`port`) USING BTREE,
  KEY `poe` (`poe`) USING BTREE,
  KEY `port_status` (`port_status`) USING BTREE,
  KEY `mac_count` (`mac_count`),
  KEY `idx_switch_mac_count` (`id_switch`,`mac_count`),
  CONSTRAINT `sw_port_info_ibfk_1` FOREIGN KEY (`id_switch`) REFERENCES `hardware` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `sw_port_neighbor` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `hardware_id` int(11) NOT NULL,
  `port_num` int(11) DEFAULT NULL COMMENT 'Номер порта как в sw_port_info (NULL — LAG и пр.)',
  `port` varchar(64) NOT NULL COMMENT 'Имя порта на устройстве (0/12, sfp28-1)',
  `neighbor_name` varchar(255) DEFAULT NULL COMMENT 'System Name соседа',
  `neighbor_port` varchar(255) DEFAULT NULL COMMENT 'Порт соседа (Port ID)',
  `neighbor_mac` char(17) DEFAULT NULL COMMENT 'Chassis ID соседа',
  `proto` varchar(10) NOT NULL DEFAULT 'lldp',
  `seen_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_hw_port_mac` (`hardware_id`,`port`,`neighbor_mac`) USING BTREE,
  KEY `idx_hw_num` (`hardware_id`,`port_num`) USING BTREE,
  CONSTRAINT `sw_port_neighbor_ibfk_1` FOREIGN KEY (`hardware_id`) REFERENCES `hardware` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE IF NOT EXISTS `users_devices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fio` varchar(255) NOT NULL,
  `host` varchar(50) DEFAULT NULL,
  `mac` varchar(17) DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `last_seen` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `mac` (`mac`) USING BTREE,
  KEY `Индекс 3` (`host`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


